select jsonb_build_object('observedAt',clock_timestamp(),'migrationCount',(select count(*) from supabase_migrations.schema_migrations),'migrationMax',(select max(version) from supabase_migrations.schema_migrations),'versions',(select jsonb_agg(version order by version) from supabase_migrations.schema_migrations),'objects',jsonb_build_object('workerControl',to_regclass('turn_private.hosted_worker_control') is not null,'workerHeartbeats',to_regclass('turn_private.hosted_worker_heartbeats') is not null,'work',to_regclass('turn_private.work') is not null,'turnDataSchema',to_regnamespace('turn_data_private') is not null,'qaSubmit',(select count(*)>0 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='qa_submit_message_v1'),'qaReadyGroups',(select count(*)>0 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='qa_ready_groups_v1'),'qaFunctions',(select count(*) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in('public','turn_private') and p.proname like 'qa_%'))) as metadata;

select jsonb_build_object('observedAt',clock_timestamp(),'control',jsonb_build_object('rows',(select count(*) from turn_private.hosted_worker_control),'enabled',(select bool_or(enabled) from turn_private.hosted_worker_control)),'heartbeats',jsonb_build_object('rows',(select count(*) from turn_private.hosted_worker_heartbeats),'recent60s',(select count(*) from turn_private.hosted_worker_heartbeats where last_seen_at>clock_timestamp()-interval '60 seconds'),'activePhases',(select count(*) from turn_private.hosted_worker_heartbeats where phase in ('started','polling','idle','draining') and last_seen_at>clock_timestamp()-interval '60 seconds')),'work',jsonb_build_object('rows',(select count(*) from turn_private.work),'ready',(select count(*) from turn_private.work where state='queued' or (state='leased' and expires_at<=clock_timestamp())),'leasedCurrent',(select count(*) from turn_private.work where state='leased' and expires_at>clock_timestamp()),'leasedExpired',(select count(*) from turn_private.work where state='leased' and expires_at<=clock_timestamp())),'qaReadyGroups','UNKNOWN_RPC_NOT_APPLIED') as metadata;

select jsonb_build_object('observedAt',clock_timestamp(),'observationPidExcluded',true,'readAllStatsMember',pg_has_role(current_user,'pg_read_all_stats','MEMBER'),'groups',(select coalesce(jsonb_agg(to_jsonb(g) order by role_bucket,state_bucket),'[]'::jsonb) from (select case when usename in ('postgres','supabase_admin','supabase_auth_admin','supabase_storage_admin','supabase_realtime_admin','authenticator','service_role','anon','authenticated','cli_login_postgres','pgbouncer','supabase_replication_admin','dashboard_user','supabase_read_only_user') then usename else 'OTHER_OR_HIDDEN' end role_bucket,case when state in ('active','idle','idle in transaction','idle in transaction (aborted)','fastpath function call','disabled') then state else 'OTHER_OR_HIDDEN' end state_bucket,count(*) backends,count(*) filter(where xact_start is not null) with_transaction,count(*) filter(where backend_xid is not null) with_backend_xid,count(*) filter(where backend_xmin is not null) with_backend_xmin,count(*) filter(where state is null) hidden_state,coalesce(floor(max(extract(epoch from clock_timestamp()-xact_start))),0)::bigint oldest_transaction_seconds from pg_stat_activity where datname=current_database() and pid<>pg_backend_pid() group by 1,2) g)) as metadata;

select jsonb_build_object('observedAt',clock_timestamp(),'database',jsonb_build_object('statsReset',d.stats_reset,'inserted',d.tup_inserted,'updated',d.tup_updated,'deleted',d.tup_deleted,'commits',d.xact_commit,'rollbacks',d.xact_rollback),'tables',(select coalesce(jsonb_agg(jsonb_build_object('schema',schemaname,'table',relname,'inserted',n_tup_ins,'updated',n_tup_upd,'deleted',n_tup_del,'hotUpdated',n_tup_hot_upd,'liveEstimate',n_live_tup,'deadEstimate',n_dead_tup) order by schemaname,relname),'[]'::jsonb) from pg_stat_user_tables where schemaname in ('public','auth','storage','private','identity_private','knowledge_review_private','turn_private','supabase_migrations','community_private','ops_budget_private','place_quota_private','privacy_private','research_intake_private','service_cases_private','realtime','vault')) ) as metadata from pg_stat_database d where d.datname=current_database();
